import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"対応表の見直しと、実用性の注意","description":"Mutelinkの翻訳エンジンの対応表と品質上の注意。Azure・PLaMo・TranslateGemmaの実測結果に基づく対応言語の判断を説明します。","frontmatter":{"description":"Mutelinkの翻訳エンジンの対応表と品質上の注意。Azure・PLaMo・TranslateGemmaの実測結果に基づく対応言語の判断を説明します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"対応表の見直しと、実用性の注意 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkの翻訳エンジンの対応表と品質上の注意。Azure・PLaMo・TranslateGemmaの実測結果に基づく対応言語の判断を説明します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"対応表の見直しと、実用性の注意 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkの翻訳エンジンの対応表と品質上の注意。Azure・PLaMo・TranslateGemmaの実測結果に基づく対応言語の判断を説明します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}]]},"headers":[],"relativePath":"compare/translation/review.md","filePath":"compare/translation/review.md"}'),i={name:"compare/translation/review.md"};function o(d,t,l,h,s,m){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="対応表の見直しと、実用性の注意" tabindex="-1">対応表の見直しと、実用性の注意 <a class="header-anchor" href="#対応表の見直しと、実用性の注意" aria-label="Permalink to &quot;対応表の見直しと、実用性の注意&quot;">​</a></h1><p><a href="./../translation">比較一覧</a></p><h2 id="判断の範囲" tabindex="-1">判断の範囲 <a class="header-anchor" href="#判断の範囲" aria-label="Permalink to &quot;判断の範囲&quot;">​</a></h2><p>今回の5,040件はすべて要求が成功して非空のテキストを返した。しかし、要求成功は翻訳の対応・品質を保証しない。以下はモデルが指定言語で翻訳する機能の採否であり、全件の意味・自然さを母語話者が合格判定したという意味ではない。全件の生出力は各言語ページで読める。</p><h2 id="translategemmaで復帰する3言語" tabindex="-1">TranslateGemmaで復帰する3言語 <a class="header-anchor" href="#translategemmaで復帰する3言語" aria-label="Permalink to &quot;TranslateGemmaで復帰する3言語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>言語</th><th>EN→X chrF</th><th>X→EN chrF</th><th>観測と判断</th></tr></thead><tbody><tr><td><a href="./zh-hant">繁体字中国語</a></td><td>46.2</td><td>71.5</td><td>両方向30/30件。英語→繁体字の30件で、簡体字特有の代表文字の混入なし。字体を含む要求どおりの出力を確認。</td></tr><tr><td><a href="./ms">マレー語</a></td><td>67.2</td><td>72.6</td><td>両方向30/30件。モデル内テンプレートにもmsがある。指定言語で訳せるため復帰。ただし意味の逆転例あり。</td></tr><tr><td><a href="./tl">フィリピン語</a></td><td>58.2</td><td>71.5</td><td>両方向30/30件。モデル内テンプレートにtlがある。指定言語で訳せるため復帰。ただしVR用語の誤訳例あり。</td></tr></tbody></table><h3 id="品質上の注意例" tabindex="-1">品質上の注意例 <a class="header-anchor" href="#品質上の注意例" aria-label="Permalink to &quot;品質上の注意例&quot;">​</a></h3><ul><li>Gemma・マレー語のEN→X #10: 「マイクが壊れている」に対し、<code>Mikrofon saya berfungsi dengan baik</code>（マイクは正常に動いている）と、肝心な意味が逆転した。指定言語での生成自体はできるが、無確認で重要な内容を伝える用途には注意が要る。</li><li>Gemma・フィリピン語のX→EN #9: VRChatのinstanceに入る文が <code>Now, I want to discuss this specific case with you.</code> と事例について話す意味になった。</li><li>Geminiではなく<strong>TranslateGemma 4B Q4_K_M</strong>の測定。PLaMoも<strong>0.8B Q4_K_M</strong>であり、別サイズへ一般化しない。</li></ul><h2 id="plamoで除外を維持する9言語" tabindex="-1">PLaMoで除外を維持する9言語 <a class="header-anchor" href="#plamoで除外を維持する9言語" aria-label="Permalink to &quot;PLaMoで除外を維持する9言語&quot;">​</a></h2><p>公式モデルの53言語一覧にない言語についても、アプリ側の許可リストを通さず直接60件ずつ要求した。英語からの訳が別言語・混在言語になり、逆方向でも未翻訳コピー等が出たため、現モデルの対応選択肢からは外す。低いchrFだけが除外理由ではない。</p><table tabindex="0"><thead><tr><th>言語</th><th>EN→X chrF</th><th>X→ENの未翻訳コピー数/30</th><th>EN→X #1の実出力（要求成功でも指定言語とは限らない）</th></tr></thead><tbody><tr><td><a href="./pt">pt</a></td><td>15.2</td><td>8/30</td><td>Hallo, a拾って好上好。</td></tr><tr><td><a href="./tr">tr</a></td><td>3.1</td><td>4/30</td><td>Hallo, சிறப்பாக அறிமுகமாகிறேன்.</td></tr><tr><td><a href="./sv">sv</a></td><td>15.6</td><td>8/30</td><td>Hallo, leuk om you kennis te maken.</td></tr><tr><td><a href="./da">da</a></td><td>1.8</td><td>19/30</td><td>नमस्ते, खुशी लाग्यो भेट भएकोमा।</td></tr><tr><td><a href="./fi">fi</a></td><td>11.5</td><td>10/30</td><td>Hallo, freundlich kennenzulernen.</td></tr><tr><td><a href="./cs">cs</a></td><td>11.0</td><td>0/30</td><td>Hallo, leuk je jeter.</td></tr><tr><td><a href="./el">el</a></td><td>2.2</td><td>10/30</td><td>Hallo, leuke jeter.</td></tr><tr><td><a href="./ro">ro</a></td><td>3.0</td><td>13/30</td><td>नमस्ते, खुश लինուँ भेटेकोमा।</td></tr><tr><td><a href="./uk">uk</a></td><td>18.8</td><td>0/30</td><td>Hallo, приятно познакомиться.</td></tr></tbody></table><p>PLaMoは既存19言語（英語を含め20言語）を維持し、Azureは今回の28言語すべてを維持する。TranslateGemmaは今回の全28言語＋英語を選択可能にする。品質の比較は同じ言語・方向内で行い、異なる言語間のchrFをそのまま優劣にしない。</p><h2 id="検証データの由来" tabindex="-1">検証データの由来 <a class="header-anchor" href="#検証データの由来" aria-label="Permalink to &quot;検証データの由来&quot;">​</a></h2><p>既存26言語の参考文は以前のClaude作成、追加の繁体字/フィリピン語はCodexによるAI作成で、母語話者校正はない。全出力を閲覧できるようにすることで、数値や「実験的」というラベルだけに頼らず判断する。公開後の母語話者レビューは、原出力を書き換えず別注記として残す。</p>',14)])])}const p=e(i,[["render",o]]);export{c as __pageData,p as default};
